5	/**
6	 * Add submenu in menu "Media"
7	 *
8	 * @since  1.5
9	 * @author Jonathan Buttigieg
10	 */
11	function _imagify_ngg_bulk_optimization_menu() {
12		if ( ! defined( 'NGGFOLDER' ) ) {
13			return;
14		}
15	
16		$capacity = imagify_get_context( 'ngg' )->get_capacity( 'bulk-optimize' );
17	
18		add_submenu_page( NGGFOLDER, __( 'Bulk Optimization', 'imagify' ), __( 'Bulk Optimization', 'imagify' ), $capacity, imagify_get_ngg_bulk_screen_slug(), '_imagify_display_bulk_page' );
19	}
