3	
4	add_filter( 'imagify_bulk_page_types', 'imagify_ngg_bulk_page_types' );
5	/**
6	 * Filter the types to display in the bulk optimization page.
7	 *
8	 * @since  1.7.1
9	 * @author Grégory Viguier
10	 *
11	 * @param  array $types The folder types displayed on the page. If a folder type is "library", the context should be suffixed after a pipe character. They are passed as array keys.
12	 * @return array
13	 */
14	function imagify_ngg_bulk_page_types( $types ) {
15		if ( ! empty( $_GET['page'] ) && imagify_get_ngg_bulk_screen_slug() === $_GET['page'] ) { // WPCS: CSRF ok.
16			$types['library|ngg'] = 1;
17		}
18	
19		return $types;
20	}
21	
22	add_filter( 'imagify_bulk_stats', 'imagify_ngg_bulk_stats', 10, 2 );
23	/**
24	 * Filter the generic stats used in the bulk optimization page.
25	 *
26	 * @since  1.7.1
27	 * @author Grégory Viguier
28	 *
29	 * @param  array $data  The data.
30	 * @param  array $types The folder types. They are passed as array keys.
31	 * @return array
32	 */
33	function imagify_ngg_bulk_stats( $data, $types ) {
34		if ( ! isset( $types['library|ngg'] ) ) {
35			return $data;
36		}
37	
38		add_filter( 'imagify_count_saving_data', 'imagify_ngg_count_saving_data', 8 );
39		$total_saving_data = imagify_count_saving_data();
40		remove_filter( 'imagify_count_saving_data', 'imagify_ngg_count_saving_data', 8 );
41	
42		// Global chart.
43		$data['total_attachments']       += imagify_ngg_count_attachments();
44		$data['unoptimized_attachments'] += imagify_ngg_count_unoptimized_attachments();
45		$data['optimized_attachments']   += imagify_ngg_count_optimized_attachments();
46		$data['errors_attachments']      += imagify_ngg_count_error_attachments();
47		// Stats block.
48		$data['already_optimized_attachments'] += $total_saving_data['count'];
49		$data['original_human']                += $total_saving_data['original_size'];
50		$data['optimized_human']               += $total_saving_data['optimized_size'];
51	
52		return $data;
53	}
54	
55	add_filter( 'imagify_bulk_page_data', 'imagify_ngg_bulk_page_data', 10, 2 );
56	/**
57	 * Filter the data to use on the bulk optimization page.
58	 *
59	 * @since  1.7
60	 * @since  1.7.1 Added the $types parameter.
61	 * @author Grégory Viguier
62	 *
63	 * @param  array $data  The data to use.
64	 * @param  array $types The folder types displayed on the page. They are passed as array keys.
65	 * @return array
66	 */
67	function imagify_ngg_bulk_page_data( $data, $types ) {
68		if ( ! isset( $types['library|ngg'] ) ) {
69			return $data;
70		}
71	
72		// Limits.
73		$data['unoptimized_attachment_limit'] += imagify_get_unoptimized_attachment_limit();
74		// Group.
75		$data['groups']['ngg'] = [
76			/**
77			 * The group_id corresponds to the file names like 'part-bulk-optimization-results-row-{$group_id}'.
78			 * It is also used in get_imagify_localize_script_translations().
79			 */
80			'group_id' => 'library',
81			'context'  => 'ngg',
82			'title'    => __( 'NextGen Galleries', 'imagify' ),
83			/* translators: 1 is the opening of a link, 2 is the closing of this link. */
84			'footer'   => sprintf( __( 'You can also re-optimize your images more finely directly in each %1$sgallery%2$s.', 'imagify' ), '<a href="' . esc_url( admin_url( 'admin.php?page=nggallery-manage-gallery' ) ) . '">', '</a>' ),
85		];
86	
87		return $data;
88	}
89	
90	add_filter( 'imagify_optimization_errors_url', 'imagify_ngg_optimization_errors_url', 10, 2 );
91	/**
92	 * Provide a URL to a page displaying optimization errors for the NGG context.
93	 *
94	 * @since  1.9
95	 * @author Grégory Viguier
96	 *
97	 * @param  string $url     The URL.
98	 * @param  string $context The context.
99	 * @return string
100	 */
101	function imagify_ngg_optimization_errors_url( $url, $context ) {
102		if ( 'ngg' === $context ) {
103			return admin_url( 'admin.php?page=nggallery-manage-gallery' );
104		}
105	
106		return $url;
107	}
