1	<?php
2	// phpcs:ignore Generic.Files.OneObjectStructurePerFile.MultipleFound
3	
4	/**
5	 * NextGen admin module.
6	 */
7	class M_NextGen_Admin extends C_Base_Module {
8	
9		/**
10		 * Object instance.
11		 *
12		 * @var object
13		 */
14		public $object;
15	
16		/**
17		 * Defines the module
18		 */
19		public function define(
20			$id = 'pope-module',
21			$name = 'Pope Module',
22			$description = '',
23			$version = '',
24			$uri = '',
25			$author = '',
26			$author_uri = '',
27			$context = false
28		) {
29			parent::define(
30				'photocrati-nextgen_admin',
31				'NextGEN Administration',
32				'Provides a framework for adding Administration pages',
33				'3.7.0',
34				'https://www.imagely.com/wordpress-gallery-plugin/nextgen-gallery/',
35				'Imagely',
36				'https://www.imagely.com'
37			);
38	
39			\Imagely\NGG\Util\Installer::add_handler( $this->module_id, 'C_NextGen_Admin_Installer' );
40	
41			\Imagely\NGG\Settings\Settings::get_instance()->add_option_handler(
42				'C_NextGen_Admin_Option_Handler',
43				[
44					'jquery_ui_theme_url',
45				]
46			);
47	
48			if ( is_multisite() ) {
49				\Imagely\NGG\Settings\GlobalSettings::get_instance()->add_option_handler(
50					'C_NextGen_Admin_Option_Handler',
51					[
52						'jquery_ui_theme_url',
53					]
54				);
55			}
56		}
57	
58		/**
59		 * Register utilities necessary for this module (and the plugin)
60		 */
61		public function _register_utilities() {
62			$this->get_registry()->add_utility( 'I_NextGen_Admin_Page', 'C_NextGen_Admin_Page_Controller' );
63			$this->get_registry()->add_utility( 'I_Page_Manager', 'C_NextGen_Admin_Page_Manager' );
64			$this->get_registry()->add_utility( 'I_Form', 'C_Form' );
65		}
66	
67		/**
68		 * Registers adapters required by this module
69		 */
70		public function _register_adapters() {
71			$this->get_registry()->add_adapter( 'I_MVC_Controller', 'A_MVC_Validation' );
72		}
73	
74		public function get_common_admin_css_handlers( $handlers ) {
75			$handlers['nextgen_admin_css'] = $this->module_version;
76			return $handlers;
77		}
78	
79		public function get_common_admin_js_handlers( $handlers ) {
80			$handlers['nextgen_admin_js'] = $this->module_version;
81			return $handlers;
82		}
83	
84		// Enqueues static resources that should be enqueued in the HEADER on a NextGEN Admin Page.
85		public static function enqueue_common_admin_static_resources( $footer = false ) {
86			$footer                = ( $footer === true );
87			$script_handles_filter = $footer ? 'ngg_admin_footer_script_handles' : 'ngg_admin_script_handles';
88			$style_handles_filter  = 'ngg_admin_style_handles';
89			$enqueue_action        = $footer ? 'ngg_admin_footer_enqueue_scripts' : 'ngg_admin_enqueue_scripts';
90	
91			$slug = C_NextGen_Admin_Page_Manager::is_requested();
92			if ( $slug ) {
93				$script_handles = apply_filters( $script_handles_filter, [], $slug );
94				$style_handles  = apply_filters( $style_handles_filter, [], $slug );
95	
96				foreach ( $script_handles as $handle => $version ) {
97					$hook = "ngg_enqueue_{$handle}_script";
98					if ( has_action( $hook ) ) {
99						do_action( $hook, $handle, $version );
100					} else {
101	     // phpcs:ignore WordPress.WP.EnqueuedResourceParameters.NotInFooter
102						wp_enqueue_script( $handle, '', [], $version );
103					}
104				}
105	
106				if ( ! $footer ) {
107					foreach ( $style_handles as $handle => $version ) {
108						$hook = "ngg_enqueue_{$handle}_style";
109						if ( has_action( $hook ) ) {
110							do_action( $hook, $handle, $version );
111						} else {
112							wp_enqueue_style( $handle, '', [], $version );
113						}
114					}
115				}
116	
117				// Expose a means for other modules or third-party plugins to provide their own
118				// enqueue calls.
119				do_action( $enqueue_action, $slug );
120			}
121	
122			// Have the toplevel "NextGEN Gallery" link to the Manage Galleries page.
123			wp_add_inline_script(
124				'common',
125				"jQuery(function($){
126	            var parent = $('.toplevel_page_nextgen-gallery');
127	            var manageGalleryUrl = parent.find('a[href*=\"manage-gallery\"]').attr('href');
128	            parent.attr('href', manageGalleryUrl);
129	        })"
130			);
131		}
132	
133		// Enqueues static resources that should be enqueued in the FOOTER on a NextGEN Admin Page.
134		public function enqueue_common_admin_footer_static_resources() {
135			self::enqueue_common_admin_static_resources( true );
136		}
137	
138		/**
139		 * Hooks into the WordPress Framework
140		 */
141		public function _register_hooks() {
142			// Register scripts.
143			add_action( 'init', [ $this, 'register_scripts' ], 9 );
144	
145			// Elementor's editor.php runs `new \WP_Scripts()` which requires we register scripts on both init and this
146			// action if we want our resources to be used with the page builder.
147			add_action( 'elementor/editor/before_enqueue_scripts', [ $this, 'register_scripts' ] );
148	
149			// Enqueue common static resources for NGG admin pages.
150			add_filter( 'ngg_admin_style_handles', [ $this, 'get_common_admin_css_handlers' ] );
151			add_filter( 'ngg_admin_script_handles', [ $this, 'get_common_admin_js_handlers' ] );
152			add_action( 'admin_enqueue_scripts', [ $this, 'enqueue_common_admin_static_resources' ] );
153			add_action( 'admin_footer_print_scripts', [ $this, 'enqueue_common_admin_footer_static_resources' ] );
154	
155			// Provides menu options for managing NextGEN Settings.
156			add_action( 'admin_menu', [ $this, 'add_menu_pages' ], 999 );
157	
158			// Add ngg-admin body class to all admin pages for styling.
159			add_filter( 'admin_body_class', [ $this, 'add_ngg_body_class' ] );
160	
161			// Custom post types.
162			add_filter( 'admin_body_class', [ $this, 'add_ngg_post_type_class' ] );
163			add_filter( 'screen_options_show_screen', [ $this, 'remove_post_type_screen_options' ] );
164			add_action( 'all_admin_notices', [ $this, 'custom_post_type_markup_top' ], 11 );
165			add_action( 'admin_footer', [ $this, 'custom_post_type_markup_bottom' ] );
166	
167			// Requirements need to be registered with the notification manager *before* it's serve_ajax_request().
168			add_action(
169				'after_setup_theme',
170				function () {
171					add_action( 'admin_init', [ \Imagely\NGG\Admin\RequirementsManager::get_instance(), 'create_notification' ], - 10 );
172				}
173			);
174	
175			// Define routes.
176			add_action( 'ngg_routes', [ $this, 'define_routes' ] );
177	
178			// Provides admin notices.
179			$notices = \Imagely\NGG\Admin\Notifications\Manager::get_instance();
180			add_action( 'admin_footer', [ $notices, 'enqueue_scripts' ] );
181			add_action( 'do_ngg_notices', [ $notices, 'render' ] );
182			add_action( 'ngg_created_new_gallery', [ $this, 'set_review_notice_flag' ] );
183			add_action( 'ngg_created_new_gallery', 'M_NextGEN_Admin::update_gallery_count_setting' );
184			add_action( 'ngg_delete_gallery', 'M_NextGEN_Admin::update_gallery_count_setting' );
185	
186			if ( ! self::is_ngg_legacy_page() ) {
187				add_action( 'all_admin_notices', 'M_NextGEN_Admin::emit_do_notices_action' );
188			}
189	
190			if ( defined( 'PHP_VERSION_ID' ) ) {
191				$php_id = PHP_VERSION_ID;
192			} else {
193				$version = explode( '.', PHP_VERSION );
194				$php_id  = ( $version[0] * 10000 + $version[1] * 100 + $version[2] );
195			}
196	
197			if ( $php_id < 50300 ) {
198				$notices->add(
199					'ngg_php52_deprecation',
200					[ 'message' => __( 'PHP 5.2 will be deprecated in a future version of NextGEN. Please upgrade your PHP installation to 5.3 or above.', 'nggallery' ) ]
201				);
202			}
203	
204			// Add review notices.
205			$review_notice_1 = new \Imagely\NGG\Admin\Notifications\Review(
206				[
207					'name'    => 'review_level_1',
208					'range'   => [
209						'min' => 3,
210						'max' => 8,
211					],
212					'follows' => '',
213				]
214			);
215			$review_notice_2 = new \Imagely\NGG\Admin\Notifications\Review(
216				[
217					'name'    => 'review_level_2',
218					'range'   => [
219						'min' => 10,
220						'max' => 18,
221					],
222					'follows' => &$review_notice_1,
223				]
224			);
225			$review_notice_3 = new \Imagely\NGG\Admin\Notifications\Review(
226				[
227					'name'    => 'review_level_3',
228					'range'   => [
229						'min' => 20,
230						'max' => PHP_INT_MAX,
231					],
232					'follows' => &$review_notice_2,
233				]
234			);
235			$notices->add( $review_notice_1->get_name(), $review_notice_1 );
236			$notices->add( $review_notice_2->get_name(), $review_notice_2 );
237			$notices->add( $review_notice_3->get_name(), $review_notice_3 );
238	
239			$notices->add( 'nextgen_first_run_notification', 'C_NextGen_First_Run_Notification_Wizard' );
240	
241			$notices->add( 'mailchimp_opt_in', 'C_Mailchimp_OptIn_Notice' );
242		}
243	
244		/**
245		 * Used to determine if the current request is for a NGG legacy page
246		 */
247		public static function is_ngg_legacy_page(): bool {
248			// This method only inspects the URL and returns a bool. Nonce verification is done in the methods that
249			// make use of this method.
250			//
251			// phpcs:disable WordPress.Security.NonceVerification.Recommended
252			return ( is_admin()
253					&& isset( $_REQUEST['page'] )
254	    // phpcs:ignore WordPress.PHP.StrictInArray.MissingTrueStrict
255					&& in_array(
256						sanitize_text_field( wp_unslash( $_REQUEST['page'] ) ),
257						[
258							'nggallery-manage-gallery',
259							'nggallery-manage-album',
260							'nggallery-tags',
261							'manage-galleries',
262						]
263					)
264			);
265			// phpcs:enable WordPress.Security.NonceVerification.Recommended
266		}
267	
268		/**
269		 * Emits the 'do_ngg_notices' action
270		 * Used by the notification manager to render all notices
271		 */
272		public static function emit_do_notices_action() {
273			if ( ! did_action( 'do_ngg_notices' ) ) {
274				do_action( 'do_ngg_notices' );
275			}
276		}
277	
278		/**
279		 * We do not want to suddenly ask users for a review when they have upgraded. Instead we will wait for a new
280		 * gallery to be created and then will we also consider displaying reviews if the gallery count is within range.
281		 */
282		public function set_review_notice_flag() {
283			$settings = \Imagely\NGG\Settings\Settings::get_instance();
284			if ( ! $settings->get( 'gallery_created_after_reviews_introduced' ) ) {
285				$settings->set( 'gallery_created_after_reviews_introduced', true );
286			}
287			$settings->save();
288		}
289	
290		/**
291		 * Review notifications are pegged to run only when the current gallery count is within a certain range. This
292		 * updates the 'gallery_count' setting when galleries have been created or deleted.
293		 */
294		public static function update_gallery_count_setting() {
295			$settings               = \Imagely\NGG\Settings\Settings::get_instance();
296			$mapper                 = \Imagely\NGG\DataMappers\Gallery::get_instance();
297			$original_cache_setting = $mapper->use_cache;
298			$mapper->use_cache      = false;
299			$gallery_count          = \Imagely\NGG\DataMappers\Gallery::get_instance()->count();
300			$mapper->use_cache      = $original_cache_setting;
301			$settings->set( 'gallery_count', $gallery_count );
302			$settings->save();
303			return $gallery_count;
304		}
305	
306		public function define_routes( $router ) {
