451		public static function is_block_editor(): bool {
452			$is_block_editor = false;
453			if ( function_exists( 'get_current_screen' ) ) {
454				$current_screen = get_current_screen();
455				if ( is_object( $current_screen ) ) {
456					if ( method_exists( $current_screen, 'is_block_editor' ) ) {
457						$is_block_editor = $current_screen->is_block_editor();
458					}
459	
460					if ( ! $is_block_editor ) {
461						if ( $current_screen->action == 'add' ) {
462							$is_block_editor = function_exists( 'use_block_editor_for_post_type' ) && use_block_editor_for_post_type( $current_screen->post_type );
463						} else {
464							$is_block_editor = function_exists( 'use_block_editor_for_post' ) && use_block_editor_for_post( null );
465						}
466					}
467	
468					if ( ! $is_block_editor ) {
469						// This method only determines if the block editor or classic editor are being used. Nonce
470						// verification is the responsibility of methods that invoke this method.
471						//
472						// phpcs:disable WordPress.Security.NonceVerification.Recommended
473						if ( $current_screen->action == 'add' ) {
474							$is_block_editor = ! isset( $_GET['classic-editor'] ) && function_exists( 'gutenberg_can_edit_post_type' ) && gutenberg_can_edit_post_type( $current_screen->post_type );
475						} else {
476							$is_block_editor = ! isset( $_GET['classic-editor'] ) && function_exists( 'gutenberg_can_edit_post' ) && gutenberg_can_edit_post( null );
477						}
478						// phpcs:enable WordPress.Security.NonceVerification.Recommended
479					}
480				}
481			}
482	
483			if ( ! $is_block_editor ) {
484				$is_block_editor = function_exists( 'is_gutenberg_page' ) && is_gutenberg_page();
485			}
486	
487			return $is_block_editor;
488		}
