519	class C_NextGen_Admin_Installer {
520	 // phpcs:ignore Generic.Files.OneObjectStructurePerFile.MultipleFound
521	
522		public function install() {
523			$settings = \Imagely\NGG\Settings\Settings::get_instance();
524	
525			// In version 0.2 of this module and earlier, the following values
526			// were statically set rather than dynamically using a handler. Therefore, we need
527			// to delete those static values.
528			$module_name = 'photocrati-nextgen_admin';
529			$modules     = get_option( 'pope_module_list', [] );
530			if ( ! $modules ) {
531				$modules = $settings->get( 'pope_module_list', [] );
532			}
533	
534			$cleanup = false;
535			foreach ( $modules as $module ) {
536				if ( strpos( $module, $module_name ) !== false ) {
537					// Leave $module as-is: inside version_compare() will warn about passing items by reference.
538					$module = explode( '|', $module );
539					$val    = array_pop( $module );
540					if ( version_compare( $val, '0.3' ) == -1 ) {
541						$cleanup = true;
542					}
543					break;
544				}
545			}
546	
547			if ( $cleanup ) {
548				$keys = [
549					'jquery_ui_theme',
550					'jquery_ui_theme_version',
551					'jquery_ui_theme_url',
552				];
553				foreach ( $keys as $key ) {
554					$settings->delete( $key );
555				}
556			}
557		}
558	}
