	const bodyText = await page.locator( 'body' ).innerText();
	expect( bodyText ).not.toMatch( /Fatal error/i );
	expect( bodyText ).not.toMatch( /C_Gallery_Storage/i );
} );

// ---------------------------------------------------------------------------
