    await page.getByLabel('Username or Email Address').fill('admin');
    await page.getByLabel('Password', { exact: true }).fill('password');
    await page.getByRole('button', { name: 'Log In' }).click();
    await page.waitForURL(/\/wp-admin\/?/, { timeout: 20000 });
  }

  // Navigate to NGG v4 page (React SPA)
  await page.goto('http://localhost:8888/wp-admin/admin.php?page=imagely', { waitUntil: 'domcontentloaded' });
  await page.screenshot({ path: '/tmp/verify-01-ngg-page.png', fullPage: false });
