  await bulkLink.waitFor({ state: 'visible', timeout: 10000 });
  const href = await bulkLink.getAttribute('href');
  console.log('Step 2: Bulk link href:', href);
  await page.screenshot({ path: '/tmp/verify-02-before-click.png', fullPage: false });

  // Click it — with the fix, this should do a full page navigation
  await Promise.all([
    page.waitForURL(/page=imagify-ngg-bulk-optimization/, { timeout: 15000 }),
    bulkLink.click(),
